"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["88799"],{4455(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.inscricao.rascunho_so_antes_do_envio","status":422,"titulo":"Depois do envio, a inscri\xe7\xe3o s\xf3 muda por um novo envio"},"descricao":{"codigo":"uniplus.selecao.inscricao.rascunho_so_antes_do_envio","requisitos":["UNI-REQ-0023","UNI-REQ-0165"],"oQueAconteceu":["A inscri\xe7\xe3o j\xe1 foi enviada, e s\xf3 o rascunho \xe9 gravado aos poucos. A inscri\xe7\xe3o\\nenviada vale como est\xe1, e s\xf3 muda por um novo envio com todas as respostas,\\nque emite outro comprovante (UNI-REQ-0165, UNI-REQ-0023). Por isso o pedido de\\ngravar o rascunho \xe9 recusado, antes mesmo de conferir as respostas. Esta\\nrecusa s\xf3 vem com as inscri\xe7\xf5es abertas: fora do per\xedodo, o c\xf3digo \xe9 o do\\nper\xedodo (`uniplus.selecao.inscricao.fora_do_periodo`)."],"comoResolver":["Para corrigir a inscri\xe7\xe3o, envie-a de novo com as respostas corrigidas,\\nenquanto as inscri\xe7\xf5es estiverem abertas. Cada envio gera um novo comprovante,\\ne o de maior n\xfamero \xe9 o que vale."],"ondeAparece":["Grava\xe7\xe3o do rascunho da inscri\xe7\xe3o"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Inscricao"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"3bbcc2307827ee8c6dab135295710bb856847f61"}}')}}]);